-- Recreate "semantic_nodes" empty with its original schema.
--
-- Reversibility note: this restores the table definition only. Every row the
-- up migration dropped is gone for good; this exists so a binary rolled back
-- to a release that still wrote the table finds the schema it expects.
--
-- The n_distinct estimate attribute that 20260929100000_set_semantic_nodes_-
-- trace_id_n_distinct added is deliberately not restored: statistics targets
-- are a planner hint, not schema, and re-adding it would pin an estimate for
-- a table that is empty.
CREATE TABLE IF NOT EXISTS "semantic_nodes" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 98784247808), "trace_id" character varying NOT NULL, "node_id" character varying NOT NULL, "parent_node_id" character varying NOT NULL DEFAULT '', "provider_type" character varying NOT NULL DEFAULT '', "normalized_type" character varying NOT NULL DEFAULT '', "role" character varying NOT NULL DEFAULT '', "path" character varying NOT NULL DEFAULT '', "node_index" bigint NOT NULL DEFAULT 0, "depth" bigint NOT NULL DEFAULT 0, "text_preview" character varying NOT NULL DEFAULT '', "json" character varying NOT NULL DEFAULT '', "raw" character varying NOT NULL DEFAULT '', "raw_ref" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "semanticnode_trace_id_depth_node_index" ON "semantic_nodes" ("trace_id", "depth", "node_index");
CREATE UNIQUE INDEX IF NOT EXISTS "semanticnode_trace_id_node_id" ON "semantic_nodes" ("trace_id", "node_id");
